Given an array arr[] of distinct elements, find the minimum number of swaps required to sort the array.Examples: Input: arr[] = [2, 8, 5, 4]Output: 1Explanation: Swap 8 with 4 to get the sorted array.Input: arr[] = [10, 19, 6, 3, 5]Output: 2Explanation: Swap 10 with 3 and 19 with 5 to get the sorted array.Input: arr[] = [1, 3, 4, 5, 6]Output: 0Explanation: Input array is already sorted.Try It YourselfTable of ContentBy Swapping Elements to Correct Positions - O(nlogn) Time and O(n) SpaceUsing Cycle Detection - O(nlogn) Time and O(n) SpaceBy Swapping Elements to Correct Positions - O(nlogn) Time and O(n) SpaceThe idea is to use a hash map to store each element of the given array along with its index. We also create a temporary array that stores all the elements of the input array in sorted order. As we traverse the input array, if the current element arr[i] is not in its correct position, we swap it with the element that should be at i i.e., temp[i]. After this, we increment the swap count and update the indices in the hash map accordingly.
            C++

    // C++ program to find the minimum no. of swaps required to  
// sort an array by swapping elements to correct positions

#include <bits/stdc++.h>
using namespace std;

int minSwaps(vector<int> &arr) {

    // Temporary array to store elements in sorted order
    vector<int> temp(arr.begin(), arr.end());
    sort(temp.begin(), temp.end());

  	// Hashing elements with their correct positions
  	unordered_map<int, int> pos; 
    for(int i = 0; i < arr.size(); i++)
        pos[arr[i]] = i;

  	int swaps = 0;
    for(int i = 0; i < arr.size(); i++) {
        if(temp[i] != arr[i]) {

            // Index of the element that should be at index i.
            int ind = pos[temp[i]];
            swap(arr[i], arr[ind]);

            // Update the indices in the hashmap
            pos[arr[i]] = i; 
            pos[arr[ind]] = ind;

            swaps++; 
        }
    }
    return swaps; 
}

int main() {
    vector<int> arr = {10, 19, 6, 3, 5}; 
    cout << minSwaps(arr); 
    return 0;
}


