import java.util.*;

class GfG {
    static int minSwaps(int[] arr) {

        // Temporary array to store elements in sorted order
        int[] temp = arr.clone();
        Arrays.sort(temp);

      	// Hashing elements with their correct positions
      	HashMap<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < arr.length; i++)
            pos.put(arr[i], i);

      	int swaps = 0;
        for (int i = 0; i < arr.length; i++) {
            if (temp[i] != arr[i]) {

